<?php /** @var ?array<string,mixed> $c */ /** @var list<array<string,mixed>> $campaigns */ /** @var array<string,string> $services */
$v = static fn (string $k, mixed $fallback = ''): string => (string) old($k, (string) ($fallback ?? ''));
$type = $v('discount_type', $c['discount_type'] ?? 'percent');
$sel = array_filter(explode(',', (string) ($c['eligible_services'] ?? '')));
$money = static fn (?int $m): string => $m === null ? '' : number_format($m / 100, 2, '.', ''); ?>
<fieldset class="form-block"><legend class="sr-only">Coupon details</legend>
<div class="field"><label for="code">Code</label><input id="code" name="code" required maxlength="30" value="<?= e($v('code', $c['code'] ?? '')) ?>"<?= $c !== null ? ' readonly' : '' ?>><?= $c !== null ? '<small class="muted">The code cannot be changed after it is created.</small>' : '<small class="muted">Letters, digits, - and _. Saved in capitals.</small>' ?></div>
<div class="field"><label for="description">Description <span class="muted">(internal)</span></label><input id="description" name="description" maxlength="255" value="<?= e($v('description', $c['description'] ?? '')) ?>"></div>
<div class="field"><label for="campaign">Campaign</label><select id="campaign" name="campaign"><option value="">None</option><?php foreach ($campaigns as $g) : ?><option value="<?= e($g['public_id']) ?>"<?= ($v('campaign', $c['campaign_public_id'] ?? '') === $g['public_id']) ? ' selected' : '' ?>><?= e($g['name']) ?></option><?php endforeach; ?></select></div>
<div class="field"><label for="discount_type">Discount type</label><select id="discount_type" name="discount_type"><option value="percent"<?= $type === 'percent' ? ' selected' : '' ?>>Percentage</option><option value="fixed"<?= $type === 'fixed' ? ' selected' : '' ?>>Fixed amount</option></select></div>
<div class="field"><label for="percent">Percentage <span class="muted">(if percentage)</span></label><input id="percent" name="percent" inputmode="decimal" value="<?= e($v('percent', isset($c['percent_bps']) ? rtrim(rtrim(number_format((int) $c['percent_bps'] / 100, 2, '.', ''), '0'), '.') : '')) ?>"></div>
<div class="field"><label for="max_discount">Maximum discount <span class="muted">(₹, optional, for percentage)</span></label><input id="max_discount" name="max_discount" inputmode="decimal" value="<?= e($v('max_discount', $money($c['max_discount_minor'] ?? null))) ?>"></div>
<div class="field"><label for="amount">Fixed amount <span class="muted">(₹, if fixed)</span></label><input id="amount" name="amount" inputmode="decimal" value="<?= e($v('amount', $money($c['amount_minor'] ?? null))) ?>"></div>
<div class="field"><label for="min_spend">Minimum spend <span class="muted">(₹, optional)</span></label><input id="min_spend" name="min_spend" inputmode="decimal" value="<?= e($v('min_spend', $c !== null && (int) $c['min_spend_minor'] > 0 ? $money((int) $c['min_spend_minor']) : '')) ?>"></div>
<div class="field"><label for="valid_from">Valid from</label><input id="valid_from" name="valid_from" type="date" value="<?= e($v('valid_from', $c['valid_from'] ?? '')) ?>"></div>
<div class="field"><label for="valid_until">Valid until</label><input id="valid_until" name="valid_until" type="date" value="<?= e($v('valid_until', $c['valid_until'] ?? '')) ?>"></div>
<div class="field"><label for="max_uses">Total uses <span class="muted">(empty = unlimited)</span></label><input id="max_uses" name="max_uses" inputmode="numeric" value="<?= e($v('max_uses', (string) ($c['max_uses'] ?? ''))) ?>"></div>
<div class="field"><label for="max_uses_per_client">Uses per client <span class="muted">(empty = unlimited)</span></label><input id="max_uses_per_client" name="max_uses_per_client" inputmode="numeric" value="<?= e($v('max_uses_per_client', (string) ($c['max_uses_per_client'] ?? ''))) ?>"></div>
<fieldset class="field"><legend>Eligible services <span class="muted">(none ticked = all services)</span></legend><?php foreach ($services as $code => $label) : ?><label class="check"><input type="checkbox" name="eligible_services[]" value="<?= e($code) ?>"<?= in_array($code, $sel, true) ? ' checked' : '' ?>> <?= e($label) ?></label><?php endforeach; ?></fieldset>
</fieldset>
